{
  "nl": {
    "issue": [
      {
        "text": "合同解除后，尚未履行的部分与已经履行的部分分别产生何种效力；因违约解除时解除权人能否请求违约方承担违约责任；主合同解除后担保人是否仍应承担担保责任",
        "rules": ["c566-term", "c566-1a", "c566-1b", "c566-1c", "c566-2", "c566-3"]
      }
    ],
    "conditions": [
      {
        "text": "合同已经解除（双方协议解除或者一方行使解除权），合同的权利义务关系终止",
        "rules": ["c566-term"]
      },
      {
        "text": "合同项下尚有未履行的给付义务",
        "rules": ["c566-1a"]
      },
      {
        "text": "当事人已经履行，且根据履行情况和合同性质适宜恢复原状或采取其他补救措施",
        "rules": ["c566-1b"]
      },
      {
        "text": "合同因违约而解除，请求人为解除权人，相对人为违约方",
        "rules": ["c566-2"]
      },
      {
        "text": "担保合同是主合同的从合同，并为主合同提供担保",
        "rules": ["c566-3"]
      }
    ],
    "exceptions": [
      {
        "text": "当事人另有约定的，排除违约解除后请求违约方承担违约责任",
        "rules": ["c566-2-exc"]
      },
      {
        "text": "担保合同另有约定的，担保人不再承担该担保责任",
        "rules": ["c566-3-exc"]
      }
    ],
    "effects": [
      {
        "text": "尚未履行的，终止履行，义务人不再负履行义务",
        "rules": ["c566-1a"]
      },
      {
        "text": "已经履行的，当事人可以请求恢复原状或者采取其他补救措施",
        "rules": ["c566-1b"]
      },
      {
        "text": "已经履行的，当事人有权请求赔偿损失；合同解除与损害赔偿可以并存（含可得利益）",
        "rules": ["c566-1c"]
      },
      {
        "text": "合同因违约解除的，解除权人可以请求违约方承担违约责任",
        "rules": ["c566-2"]
      },
      {
        "text": "主合同解除后，担保人对债务人应当承担的民事责任仍应当承担担保责任",
        "rules": ["c566-3"]
      }
    ],
    "priority": [
      {
        "text": "当事人另有约定的，优先于违约解除后请求承担违约责任的法定规则",
        "rules": ["c566-2-exc", "c566-2"]
      },
      {
        "text": "担保合同另有约定的，优先于主合同解除后担保责任继续存在的规则",
        "rules": ["c566-3-exc", "c566-3"]
      },
      {
        "text": "主合同解除后担保责任仍存续，构成对担保从属性的例外（学理说明）",
        "rules": ["c566-3"]
      }
    ],
    "distinguish": [
      {
        "text": "笔记所称“合同权利义务终止不影响结算和清理条款、解决争议条款的效力”属第567条，本条不设该规则",
        "rules": []
      },
      {
        "text": "第564条（解除权行使期限）、第565条（解除通知与解除生效）是解除权行使规则，不涉及解除后的法律后果",
        "rules": []
      },
      {
        "text": "LEGO 卡片把“合同目的无法实现”“解除未经通知或未获司法确认”列为条件，实为第563、565条的要件，本条不采",
        "rules": []
      },
      {
        "text": "LEGO 卡片所称“恢复原状优先于赔偿损失”于本条无明文，本条仅规定二者可并存，故不设优先规则",
        "rules": []
      }
    ]
  },
  "rules": [
