{
  "nl": {
    "issue": [
      {
        "text": "债权债务终止的法定情形，以及合同解除后合同权利义务关系的终止",
        "rules": ["c557-1", "c557-2"]
      },
      {
        "text": "合同解除的方式：协商一致解除、约定解除权的设立与行使",
        "rules": ["c562-1", "c562-2a", "c562-2b"]
      },
      {
        "text": "解除权的行使期限届满未行使时，解除权是否消灭",
        "rules": ["c564-1", "c564-2"]
      },
      {
        "text": "解除合同的通知、解除的生效时点，以及未通知而直接起诉或申请仲裁时的解除时点",
        "rules": ["c565-1a", "c565-1b", "c565-1c", "c565-1d", "c565-2"]
      }
    ],
    "conditions": [
      {
        "text": "债务已经履行、债务相互抵销、债务人依法提存标的物、债权人免除债务、债权债务同归于一人，或者法律规定、当事人约定终止的其他情形",
        "rules": ["c557-1"]
      },
      {
        "text": "当事人协商一致解除合同",
        "rules": ["c562-1"]
      },
      {
        "text": "当事人约定一方解除合同的事由，且该事由已发生、该方依约定享有解除权",
        "rules": ["c562-2a", "c562-2b"]
      },
      {
        "text": "有法定或约定的解除权行使期限而期限届满未行使；或者没有该期限时，自知道或应当知道解除事由之日起一年内不行使，或经对方催告后在合理期限内不行使",
        "rules": ["c564-1", "c564-2"]
      },
      {
        "text": "当事人一方依法主张解除合同，应当通知对方；未通知而直接以起诉或申请仲裁方式主张解除的，须经法院或仲裁机构确认",
        "rules": ["c565-1a", "c565-2"]
      }
    ],
    "exceptions": [
      {
        "text": "通知载明债务人在一定期限内不履行债务则合同自动解除的，不适用“通知到达即解除”，而自通知载明的期限届满时解除",
        "rules": ["c565-1c"]
      },
      {
        "text": "法律规定了或者当事人约定了行使期限的，不适用第564条第2款的一年期间与催告规则",
        "rules": ["c564-1"]
      }
    ],
    "effects": [
      {
        "text": "有法定情形之一的，债权债务终止",
        "rules": ["c557-1"]
      },
      {
        "text": "合同解除的，该合同的权利义务关系终止",
        "rules": ["c557-2"]
      },
      {
        "text": "解除权行使期限届满未行使，或无法定、约定期限时一年内不行使、经催告后合理期限内不行使的，解除权消灭",
        "rules": ["c564-1", "c564-2"]
      },
      {
        "text": "解除通知到达对方时合同解除",
        "rules": ["c565-1b"]
      },
      {
        "text": "未通知对方而直接起诉或申请仲裁，经确认的，合同自起诉状副本或仲裁申请书副本送达对方时解除",
        "rules": ["c565-2"]
      },
      {
        "text": "对方对解除合同有异议的，任何一方当事人均可以请求人民法院或者仲裁机构确认解除行为的效力",
        "rules": ["c565-1d"]
      }
    ],
    "priority": [
      {
        "text": "通知载明自动解除条款的，按通知载明的期限届满时解除，优先于“通知到达时解除”",
        "rules": ["c565-1c", "c565-1b"]
      },
      {
        "text": "有法定或约定解除权行使期限的，优先适用第564条第1款；第2款仅适用于没有该期限的情形",
        "rules": ["c564-1", "c564-2"]
      }
    ],
    "distinguish": [
      {
        "text": "第562条是约定解除（协商一致解除与约定解除权），与第563条法定解除（不可抗力、预期违约、根本违约等）不同，后者不以合意为前提，本行未挂载第563条",
        "rules": []
      },
      {
        "text": "第564条是解除权的消灭（一年期间、催告后合理期限），与第152条撤销权的消灭（一年、九十日、五年）不同，二者期间与起算点各异",
        "rules": []
      },
      {
        "text": "笔记：约定解除权条款既可在订立合同时约定，也可在合同订立后另行约定，只要不违反强制性规定和公序良俗；第562条第2款只规定“可以约定”，未限定约定时间",
        "rules": ["c562-2a"]
      },
      {
        "text": "LEGO 卡片所称“约定解除权优先于法定解除权”“解除后相互返还”等，法条未作规定，本行不形式化",
        "rules": []
      }
    ]
  },
